function loadOperationTypes(){return $.get("/Action/GetOperationTypes").then(n=>{n=JSON.parse(n),n&&n.IsSuccess&&(operationTypes=n.Result.reduce((n,t)=>(n[t.id]=t.typeName,n),{}))}).catch(n=>{console.error("Error fetching operation types:",n)})}function CheckOperationTypeId(n){return operationTypes[n]||""}function DownloadList(){$(".preload").show();let t={dataInizio:$("#dataInizio").val(),dataFine:$("#dataFine").val(),codiceFiscale:$("#codiceFiscale").val(),iuv:$("#iuv").val(),importoMin:$("#importoMinimo").val(),importoMax:$("#importoMassimo").val(),worked:!0,page:1,valid:null,itemsPerPage:1e8,type:"RichiesteEsitate"};const n=document.createElement("iframe");n.style.display="none";document.body.appendChild(n);$.post("/Action/GetIuvInCsv",t,function(t){n.src=t}).done(function(){$(".preload").hide()})}function FiltraRichieste(){currentPage=1;$(".preload").show();let n={dataInizio:$("#dataInizio").val(),dataFine:$("#dataFine").val(),codiceFiscale:$("#codiceFiscale").val(),iuv:$("#iuv").val(),importoMin:$("#importoMinimo").val(),importoMax:$("#importoMassimo").val(),worked:!0,page:1,valid:null,itemsPerPage:itemsPerPage};$.post("/Action/FiltraRichieste",n,function(t){let i=JSON.parse(t);GetRichieste(i.Result);CreatePaginations(n.codiceFiscale,n.iuv,n.dataInizio,n.dataFine,n.importoMin,n.importoMax,!0)})}function GetRichiestePerPage(n,t){currentPage=n;let i=$("#codiceFiscale").val(),r=$("#iuv").val(),u=$("#dataInizio").val(),f=$("#dataFine").val(),e=$("#importoMinimo").val(),o=$("#importoMassimo").val();$(".items").removeClass("selected");$(".item-"+n).addClass("selected");$.get("/Action/GetRichiesteEsitate?page="+n+"&itemsPerPage="+itemsPerPage+"&codiceFiscale="+i+"&iuv="+r+"&dataInizio="+u+"&dataFine="+f+"&importoMin="+e+"&importoMax="+o,function(n){var s=JSON.parse(n);GetRichieste(s.Result);t&&CreatePaginations(i,r,u,f,e,o,t);$(".preload").hide()})}function ChangeItemsPerPage(n){itemsPerPage=Number(n)||100;currentPage=1;$(".preload").show();GetRichiestePerPage(1,!0)}function CreatePaginations(n,t,i,r,u,f){$.get("/Action/GetRichiesteEsitate?page=1&itemsPerPage=1000000000&codiceFiscale="+n+"&iuv="+t+"&dataInizio="+i+"&dataFine="+r+"&importoMin="+u+"&importoMax="+f,function(n){var i=JSON.parse(n),t=i.Message;if($(".pagination").empty(),t>0){let i=Math.ceil(t/itemsPerPage);currentPage=Math.min(Math.max(currentPage,1),i);let r=Math.max(1,currentPage-2),u=Math.min(i,r+4);r=Math.max(1,u-4);let n="<div class='pagination-controls'>";n+="<button type='button' aria-label='Pagina precedente' "+(currentPage===1?"disabled":"onclick='GetRichiestePerPage("+(currentPage-1)+", true)'")+"><i class='las la-angle-left'><\/i><\/button>";r>1&&(n+="<button type='button' onclick='GetRichiestePerPage(1, true)' class='items item-1'>1<\/button>",r>2&&(n+="<span class='pagination-ellipsis'>…<\/span>"));for(let t=r;t<=u;t++)n+="<button type='button' onclick='GetRichiestePerPage("+t+", true)' class='items item-"+t+(t===currentPage?" selected":"")+"' aria-label='Pagina "+t+"'>"+t+"<\/button>";u<i&&(u<i-1&&(n+="<span class='pagination-ellipsis'>…<\/span>"),n+="<button type='button' onclick='GetRichiestePerPage("+i+", true)' class='items item-"+i+"'>"+i+"<\/button>");n+="<button type='button' aria-label='Pagina successiva' "+(currentPage===i?"disabled":"onclick='GetRichiestePerPage("+(currentPage+1)+", true)'")+"><i class='las la-angle-right'><\/i><\/button>";n+="<\/div><span class='pagination-summary'>"+t+(t===1?" risultato":" risultati")+"<\/span>";$(".pagination").append(n)}})}function EliminaFiltro(){$(".preload").show();let n=$("#dataInizio"),t=$("#dataFine"),i=$("#codiceFiscale"),r=$("#iuv"),u=$("#importoMinimo"),f=$("#importoMassimo");$.get("/Action/EliminaFiltroRichiesteEsitate",function(e){var o=JSON.parse(e);n.val("");t.val("");i.val("");r.val("");u.val("");f.val("");GetRichiestePerPage(1,!0)})}function GetRichieste(n){var t,i;if($(".archive-list-accepted").empty(),n!=null)if(n.length>0)for(t=0;t<n.length;t++){let r="Rata unica",f=new Date(n[t].expirationDate),e=f.toLocaleDateString("it-IT",{year:"numeric",month:"2-digit",day:"2-digit"}),u=CheckOperationTypeId(n[t].operationTypeId);n[t].numeroRata!=0&&(r=n[t].numeroRata);i="<ul><li>"+n[t].id+"<\/li><li>"+n[t].codiceIdentificativoUnivocoPagatore+"<\/li><li>"+n[t].iuv+"<\/li><li>"+u+"<\/li><li>"+n[t].price+"€<\/li>";i+=u=="Multa"?"<li>"+n[t].description+"<\/li>":"<li>"+r+"<\/li>";i+="<li>"+e+"<\/li>";i+=n[t].valid!=!0?"<li><strong style='color:#EA5555;'><i class='las la-times'><\/i>&nbsp;NON VALIDATA<\/strong><\/li>":"<li><strong><i class='las la-check'><\/i>&nbsp;ESITATA<\/strong><\/li>";i+="<\/ul>";$(".archive-list-accepted").append(i)}else $(".archive-list-accepted").append("<ul><li style='width:100%; text-align: center; padding:10px'> Nessuna richiesta trovata <\/li><\/ul>");else $(".archive-list-accepted").append("<ul><li style='width:100%; text-align: center; padding:10px'> Nessuna richiesta trovata <\/li><\/ul>");$(".preload").hide()}let itemsPerPage=100,currentDate=new Date,currentPage=1,today=currentDate.toISOString().split("T")[0];loadOperationTypes();$(function(){$(".preload").show();GetRichiestePerPage(1,!0)});